begin; select plan(30);
select has_table('public','tkid_abuse_counters','distributed abuse counters exist');
select has_table('public','tkid_erasure_runs','erasure runs exist');
select has_table('public','tkid_erasure_objects','erasure object checkpoints exist');
select has_function('public','consume_tkid_abuse_limit',array['uuid','uuid','text','text','integer','integer','timestamp with time zone'],'atomic limiter RPC exists');
select has_function('public','complete_tkid_journey_erasure',array['uuid','uuid','timestamp with time zone'],'erasure completion RPC exists');
select has_column('public','tkid_events','erased_at','normalized events support erasure');
select has_column('public','tkid_commerce_links','tkid_erased_at','Commerce links expose TKID erasure state');
insert into public.tracekit_accounts(id,account_type,name) values('d5300000-0000-0000-0000-000000000001','client','Erasure A'),('d5300000-0000-0000-0000-000000000011','client','Erasure B');
insert into public.tracekit_organizations(id,owning_account_id,name) values('d5300000-0000-0000-0000-000000000002','d5300000-0000-0000-0000-000000000001','Org A'),('d5300000-0000-0000-0000-000000000012','d5300000-0000-0000-0000-000000000011','Org B');
insert into public.tracekit_business_contexts(id,account_id,organization_id,name) values('erasure-a','d5300000-0000-0000-0000-000000000001','d5300000-0000-0000-0000-000000000002','Context A'),('erasure-b','d5300000-0000-0000-0000-000000000011','d5300000-0000-0000-0000-000000000012','Context B');
insert into public.tkid_sources(id,account_id,organization_id,business_context_id,public_source_id,environment,status,allowed_origins) values('d5300000-0000-4000-8000-000000000003','d5300000-0000-0000-0000-000000000001','d5300000-0000-0000-0000-000000000002','erasure-a','tksrc_erasure123456789','production','shadow',array['https://shop.example']),('d5300000-0000-4000-8000-000000000013','d5300000-0000-0000-0000-000000000011','d5300000-0000-0000-0000-000000000012','erasure-b','tksrc_erasure876543219','production','disabled',array['https://other.example']);
select is((select allowed from public.consume_tkid_abuse_limit('d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000003','event_accepted',repeat('a',64),2,60,'2026-08-10T00:00:00Z')),true,'first distributed request allowed');
select is((select allowed from public.consume_tkid_abuse_limit('d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000003','event_accepted',repeat('a',64),2,60,'2026-08-10T00:00:10Z')),true,'burst within limit allowed');
select is((select allowed from public.consume_tkid_abuse_limit('d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000003','event_accepted',repeat('a',64),2,60,'2026-08-10T00:00:20Z')),false,'shared limit rejects excess');
select is((select current_count from public.consume_tkid_abuse_limit('d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000003','event_accepted',repeat('a',64),2,60,'2026-08-10T00:01:00Z')),1,'window reset starts new atomic counter');
select throws_ok($sql$select * from public.consume_tkid_abuse_limit('d5300000-0000-0000-0000-000000000012','d5300000-0000-4000-8000-000000000003','event_accepted',repeat('a',64),2,60,now())$sql$,'P0002',null,'cross-Organization limiter fails closed');
select throws_ok($sql$select * from public.consume_tkid_abuse_limit('d5300000-0000-0000-0000-000000000012','d5300000-0000-4000-8000-000000000013','event_accepted',repeat('a',64),2,60,now())$sql$,'P0002',null,'disabled source cannot consume limiter');
insert into public.tkid_journeys(id,account_id,organization_id,business_context_id,source_id,started_at,expires_at,privacy_mode,source_version,normalizer_version) values('d5300000-0000-4000-8000-000000000004','d5300000-0000-0000-0000-000000000001','d5300000-0000-0000-0000-000000000002','erasure-a','d5300000-0000-4000-8000-000000000003',now(),now()+interval '2 hours','essential','v1','v1');
insert into public.tkid_browser_sessions(id,organization_id,journey_id,source_id,started_at,last_seen_at,expires_at,device_class,browser_family) values('d5300000-0000-4000-8000-000000000005','d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000004','d5300000-0000-4000-8000-000000000003',now(),now(),now()+interval '30 minutes','desktop','Example');
insert into public.tkid_checkout_sessions(id,organization_id,journey_id,browser_session_id,source_id,started_at,state) values('d5300000-0000-4000-8000-000000000006','d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000004','d5300000-0000-4000-8000-000000000005','d5300000-0000-4000-8000-000000000003',now(),'server_confirmed');
insert into public.tkid_event_evidence(id,organization_id,source_id,event_id,evidence_hash,schema_version,bounded_payload) values('d5300000-0000-4000-8000-000000000007','d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000003','d5300000-0000-4000-8000-000000000008',repeat('b',64),1,'{"offer_id":"sensitive-offer"}');
