insert into public.platform_orders(platform,platform_order_id,order_ts,status,canonical_order_id,account_id,organization_id) values('fixture','erasure-order',now(),'observed','d5300000-0000-4000-8000-000000000099','d5300000-0000-0000-0000-000000000001','d5300000-0000-0000-0000-000000000002');
insert into public.tkid_commerce_links(id,organization_id,journey_id,checkout_session_id,canonical_order_id,charge_reference,relationship,sequence_position) values('d5300000-0000-4000-8000-000000000009','d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000004','d5300000-0000-4000-8000-000000000006','d5300000-0000-4000-8000-000000000099','charge-sensitive','main',0);
insert into public.tkid_erasure_runs(id,organization_id,journey_id,policy_id,actor_context,reason_code,status) values('d5300000-0000-4000-8000-000000000020','d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000004','approved-policy','privacy_request_worker','approved_request','running');
insert into public.tkid_erasure_objects(organization_id,erasure_run_id,evidence_id,object_reference,status) values('d5300000-0000-0000-0000-000000000002','d5300000-0000-4000-8000-000000000020','d5300000-0000-4000-8000-000000000007','private/tkid/object','pending');
select throws_ok($sql$select public.complete_tkid_journey_erasure('d5300000-0000-4000-8000-000000000020','d5300000-0000-0000-0000-000000000002',now())$sql$,'55000',null,'database tombstone waits for object deletion');
update public.tkid_erasure_objects set status='erased',erased_at=now() where erasure_run_id='d5300000-0000-4000-8000-000000000020';
select is(public.complete_tkid_journey_erasure('d5300000-0000-4000-8000-000000000020','d5300000-0000-0000-0000-000000000002',now()),true,'authorized erasure completes');
select is((select state from public.tkid_journeys where id='d5300000-0000-4000-8000-000000000004'),'erased','Journey becomes erased tombstone');
select is((select completeness from public.tkid_journeys where id='d5300000-0000-4000-8000-000000000004'),'erased','Journey completeness is explicit');
select is((select bounded_payload from public.tkid_event_evidence where id='d5300000-0000-4000-8000-000000000007'),'{}'::jsonb,'bounded Evidence content redacted');
select is((select offer_id from public.tkid_events where id='d5300000-0000-4000-8000-000000000008'),null,'normalized behavior redacted');
select is((select browser_family from public.tkid_browser_sessions where id='d5300000-0000-4000-8000-000000000005'),null,'device metadata redacted');
select is((select state from public.tkid_checkout_sessions where id='d5300000-0000-4000-8000-000000000006'),'server_confirmed','authoritative checkout truth preserved');
select is((select canonical_order_id from public.tkid_commerce_links where id='d5300000-0000-4000-8000-000000000009'),'d5300000-0000-4000-8000-000000000099'::uuid,'canonical Commerce identity preserved');
select ok((select tkid_erased_at is not null from public.tkid_commerce_links where id='d5300000-0000-4000-8000-000000000009'),'TKID link marked erased');
select is(public.complete_tkid_journey_erasure('d5300000-0000-4000-8000-000000000020','d5300000-0000-0000-0000-000000000002',now()),true,'second completion is idempotent');
select is(public.complete_tkid_journey_erasure('d5300000-0000-4000-8000-000000000020','d5300000-0000-0000-0000-000000000012',now()),false,'cross-Organization erasure discloses nothing');
select ok((select relrowsecurity from pg_class where oid='public.tkid_abuse_counters'::regclass),'limiter state RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.tkid_erasure_runs'::regclass),'erasure state RLS enabled');
select is((select count(*)::integer from information_schema.role_table_grants where table_schema='public' and table_name in('tkid_abuse_counters','tkid_erasure_runs','tkid_erasure_objects') and grantee in('anon','authenticated')),0,'browser receives no direct access');
select is((select count(*)::integer from public.commerce_repository_activation),0,'migration activates no repository');
select is((select count(*)::integer from public.commerce_sync_schedules where enabled),0,'migration enables no schedule');
select * from finish(); rollback;
